CREATE OR REPLACE FUNCTION public.finance_prevent_posted_entry_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
        BEGIN
            IF OLD.status = 'posted' OR OLD.posted_at IS NOT NULL THEN
                RAISE EXCEPTION 'posted journal entries are immutable';
            END IF;
            RETURN OLD;
        END;
        $function$

function.body:
