'entry_triggers',(SELECT json_agg(json_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))) FROM pg_trigger t WHERE t.tgrelid='public.journal_entries'::regclass AND NOT t.tgisinternal),
'line_triggers',(SELECT json_agg(json_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))) FROM pg_trigger t WHERE t.tgrelid='public.journal_lines'::regclass AND NOT t.tgisinternal));
